P.attack=function(e){const hp=e?.hp||0;old.attack.call(this,e);if(!active(this)||!e||e.hp>=hp)return;const p=state(this);if([1,3].includes(this.h.cell)){p.motion={profile:'piston-jab',start:this.time,duration:.42};p.combo=Math.min(8,p.combo+1);if(p.breath>0)this.c.mp=Math.min(100,this.c.mp+4);if(p.focus>0)heal(this,this.stats().maxHP*.01);}};
