P.autoSkillReady=function(d,t){if(!active(this)||d.actions[0]?.op!=='priest-kit')return old.auto.call(this,d,t);const p=state(this),kind=d.actions[0].kind,max=this.stats().maxHP;if(['novice-mend','priest-prayer'].includes(kind)&&this.c.hp>max*.8)return false;if(kind==='grace-prayer'&&this.c.hp>max*.85&&p.grace>=5)return false;if(['faith-ward','cathedral-ward'].includes(kind)&&p.ward>2&&this.c.shield>max*.08)return false;if(kind==='ritual-interrupt'&&!live(this).some(e=>E.dist(this.c,e)<=460&&(e.aim||(e.priestSeal||0)>=2)))return false;if(kind==='holy-ignition'&&!near(this,t,125).some(e=>e.priestBrand))return false;return true;};
